const html="<!doctype html>\n<html lang=\"pt\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Africa Analogs · Explorador planetário</title><style>\n*{box-sizing:border-box} :root{--bg:#0b1011;--panel:#12191a;--line:#283232;--muted:#94a5a1;--lime:#d6f28a;--rust:#d69b72}body{margin:0;background:var(--bg);color:#ecf0e7;font:14px/1.5 Arial,sans-serif}button,input,select{font:inherit}button,a{ -webkit-tap-highlight-color:transparent}button{cursor:pointer;color:inherit;border:1px solid var(--line);background:#1b2524;border-radius:6px;padding:10px 14px}button:hover{border-color:var(--lime)}button:focus-visible,a:focus-visible,input:focus-visible{outline:2px solid var(--lime);outline-offset:3px}a{color:var(--lime)}header{height:82px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 38px;gap:20px}.brand{font-weight:800;font-size:19px;letter-spacing:2px;display:flex;align-items:center;gap:13px}.mark{font-size:30px;color:var(--lime)}small,.eyebrow{font-size:10px;letter-spacing:2px;color:var(--muted);text-transform:uppercase}.badge{border:1px solid #49573c;background:#202b1d;color:var(--lime);padding:6px 10px;border-radius:30px;font-size:10px;letter-spacing:1px}.toplinks{display:flex;gap:26px;align-items:center}.toplinks a{color:var(--muted);text-decoration:none;font-size:12px}main{padding:35px 38px;max-width:1800px;margin:auto}.intro{display:flex;align-items:end;justify-content:space-between;margin-bottom:27px;gap:20px}h1{font-size:36px;letter-spacing:-1.5px;margin:8px 0;font-weight:500}.intro p{margin:0;color:var(--muted);max-width:620px}.target{display:flex;gap:4px;background:var(--panel);padding:5px;border:1px solid var(--line);border-radius:8px}.target button{border:0;background:none;min-width:94px}.target button.active,.primary{background:var(--lime);color:#172014}.workspace{display:grid;grid-template-columns:270px minmax(360px,1fr) 315px;border:1px solid var(--line);border-radius:10px;overflow:hidden;min-height:590px}.sidebar,.detail{background:var(--panel);padding:22px}.sidebar{border-right:1px solid var(--line)}.detail{border-left:1px solid var(--line)}h2{font-size:17px;font-weight:500;margin:0 0 15px}input[type=search],select{width:100%;background:#0c1313;color:#e7ede3;border:1px solid var(--line);border-radius:5px;padding:11px;margin:0 0 15px}label{display:block;color:var(--muted);font-size:12px}.site{display:block;width:100%;text-align:left;margin:7px 0;background:transparent;padding:13px 10px}.site.selected{background:#263026;border-color:#748353}.site strong{font-size:13px;font-weight:500}.site span{display:block;font-size:11px;color:var(--muted);margin-top:3px}.site b{float:right;color:var(--lime);font-size:12px}.section-label{display:flex;justify-content:space-between;margin:20px 0 10px}.map{position:relative;background:radial-gradient(ellipse at 40% 45%,#303627 0,#192824 45%,#0f2023 80%);overflow:hidden;min-height:590px}.map svg{width:100%;height:100%;position:absolute;inset:0}.map .country{fill:#2c352b;stroke:#66705b;stroke-width:1}.map text{fill:#a1ad98;font-size:10px;letter-spacing:2px}.map .pin{cursor:pointer;fill:var(--lime);stroke:#172519;stroke-width:5;transition:r .2s}.map .pin:hover,.map .pin.chosen{r:12;fill:#fff2bb}.maptitle{position:absolute;top:20px;left:20px;z-index:1;background:#111a17dc;border:1px solid #384337;padding:9px 12px;border-radius:5px;font-size:11px;letter-spacing:1px}.mapnote{position:absolute;bottom:16px;left:18px;color:#c1cbb7;font-size:10px;background:#101917dc;padding:7px 10px}.zoom{position:absolute;right:16px;top:18px;display:grid;gap:5px}.zoom button{background:#16201d;padding:5px 13px;font-size:20px}.legend{position:absolute;bottom:50px;left:18px;font-size:10px;color:#b8c4b1}.legend i{display:inline-block;width:7px;height:7px;background:var(--lime);border-radius:50%;margin-right:6px}.terrain-lines{fill:none;stroke:#8c9b66;stroke-width:.7;opacity:.19}.detail .eyebrow{color:var(--lime)}.detail h2{font-size:25px;line-height:1.2;margin:12px 0 7px}.sub{color:var(--muted);font-size:12px}.scorebox{display:flex;gap:18px;align-items:center;margin:23px 0}.ring{width:86px;height:86px;flex-shrink:0;border:6px solid #536744;border-top-color:var(--lime);border-right-color:var(--lime);border-radius:50%;display:grid;place-items:center;font-size:28px}.scorebox p{font-size:12px;margin:0}.scorebox small{font-size:9px;letter-spacing:1px}.metric{margin:13px 0;font-size:11px}.metric div{display:flex;justify-content:space-between;margin-bottom:5px}.bar{height:4px;background:#28352e;border-radius:3px}.bar i{height:100%;display:block;background:#b5ce83;border-radius:3px}.notice{padding:11px;background:#24271c;color:#c9c5a5;border:1px solid #3c412b;font-size:10px;margin:18px 0}.detail button{width:100%;margin-top:7px;font-size:12px}.bottom{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:20px}.card{border:1px solid var(--line);border-radius:9px;background:var(--panel);padding:23px}.cardhead{display:flex;justify-content:space-between;gap:12px}.card p{color:var(--muted);font-size:12px}.weights{display:grid;grid-template-columns:1fr 1fr;gap:15px}input[type=range]{width:100%;accent-color:var(--lime)}.weights label span{float:right;color:#dce9c8}#answer{font-size:12px;line-height:1.8;color:#cbd4c6;white-space:pre-wrap}.question{display:flex;gap:8px;margin-top:15px}.question input{background:#0c1313;color:white;border:1px solid var(--line);border-radius:5px;padding:10px;min-width:0;flex:1}.stack{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin-top:20px}.stack a{display:block;text-decoration:none;border:1px solid var(--line);border-radius:6px;padding:15px;color:#dce3d7}.stack span{display:block;font-size:10px;color:var(--muted);margin-top:4px}.footer{color:var(--muted);font-size:10px;display:flex;justify-content:space-between;margin-top:25px;gap:20px}#toast{position:fixed;bottom:25px;left:50%;transform:translateX(-50%);background:var(--lime);color:#172014;padding:12px 22px;border-radius:6px;display:none;z-index:9}.empty{color:var(--muted);font-size:12px}dialog{background:var(--panel);color:#eaf0e4;border:1px solid #526245;border-radius:10px;max-width:650px;width:90%;padding:26px}dialog::backdrop{background:#000a}dialog p{font-size:13px;color:var(--muted)}@media(min-width:1500px){.workspace{grid-template-columns:290px 1fr 345px;min-height:660px}.map{min-height:660px}}@media(max-width:1100px){.workspace{grid-template-columns:230px 1fr}.detail{grid-column:1/-1;border-top:1px solid var(--line);border-left:0;display:grid;grid-template-columns:1fr 1fr;gap:0 30px}.stack{grid-template-columns:repeat(3,1fr)}}@media(max-width:700px){header{padding:0 18px;height:70px}.toplinks a{display:none}.brand{font-size:14px}main{padding:25px 16px}h1{font-size:29px}.intro{display:block}.target{margin-top:20px;width:max-content}.workspace{display:block}.sidebar{border-right:0}.map{min-height:450px}.detail{display:block}.bottom{grid-template-columns:1fr}.stack{grid-template-columns:repeat(2,1fr)}.footer{display:block}.site{padding:9px}.sidebar #sites{max-height:220px;overflow:auto}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}\n</style></head><body>\n<header><div class=\"brand\"><span class=\"mark\">◉</span> AFRICA ANALOGS</div><nav class=\"toplinks\"><a href=\"#explore\">Explorador</a><a href=\"#method\">Metodologia</a><a href=\"#tools\">Ecossistema</a><span class=\"badge\">PROTÓTIPO · DEMO</span></nav></header>\n<main><section class=\"intro\"><div><div class=\"eyebrow\">EARTH ANALOGS FOR MOON AND MARS / SADC</div><h1>A próxima fronteira começa aqui.</h1><p>Explore paisagens africanas. Compare ambientes planetários. Prepare novas perguntas científicas.</p></div><div class=\"target\" role=\"group\" aria-label=\"Destino planetário\"><button class=\"active\" data-target=\"Mars\">◉ Marte</button><button data-target=\"Moon\">◐ Lua</button></div></section>\n<section id=\"explore\" class=\"workspace\"><aside class=\"sidebar\"><h2>Descobrir análogos <span style=\"color:var(--lime)\">↗</span></h2><input type=\"search\" id=\"search\" aria-label=\"Pesquisar locais\" placeholder=\"⌕  Local ou país\"><label for=\"country\">Região de investigação</label><select id=\"country\"><option value=\"\">Toda a África Austral</option>Namíbia</option>Botswana</option>África do Sul</option>Lesoto</option></select><div class=\"section-label\"><small>LOCAIS CANDIDATOS</small><small id=\"count\"></small></div><div id=\"sites\"></div><div class=\"section-label\"><small>CAMADAS</small></div><label><input id=\"relief\" type=\"checkbox\" checked> Relevo esquemático</label><label><input id=\"labels\" type=\"checkbox\" checked> Países e referências</label><div class=\"notice\">Catálogo de demonstração. Coordenadas aproximadas; pontuações e parâmetros sintéticos.</div></aside>\n<div class=\"map\" aria-label=\"Mapa esquemático interativo da África Austral\"><div class=\"maptitle\">ÁFRICA AUSTRAL <span style=\"color:var(--lime)\"> / TERRA</span></div><svg viewBox=\"0 0 600 640\" role=\"img\" aria-label=\"Locais candidatos na África Austral\"><defs><pattern id=\"grid\" width=\"60\" height=\"60\" patternUnits=\"userSpaceOnUse\"><path d=\"M60 0H0V60\" fill=\"none\" stroke=\"#97ac88\" opacity=\".09\"/></pattern><filter id=\"noise\"><feTurbulence type=\"fractalNoise\" baseFrequency=\".045\" numOctaves=\"3\" seed=\"8\"/><feColorMatrix type=\"saturate\" values=\"0\"/><feComponentTransfer><feFuncA type=\"linear\" slope=\".12\"/></feComponentTransfer></filter></defs><rect width=\"600\" height=\"640\" fill=\"url(#grid)\"/><g id=\"geography\"><path class=\"country\" d=\"M86 40L215 35 232 155 175 176 115 165 97 107Z\"/><path class=\"country\" d=\"M215 35L328 35 344 104 298 150 232 155Z\"/><path class=\"country\" d=\"M328 35L418 58 435 136 344 104Z\"/><path class=\"country\" d=\"M115 165L175 176 232 155 227 330 174 366 140 285Z\"/><path class=\"country\" d=\"M232 155L298 150 332 205 304 301 227 330Z\"/><path class=\"country\" d=\"M298 150L344 104 435 136 401 202 332 205Z\"/><path class=\"country\" d=\"M435 136L471 152 451 263 390 353 365 300 401 202Z\"/><path class=\"country\" d=\"M174 366L227 330 304 301 332 205 365 300 390 353 340 425 263 471 211 458 190 416Z\"/><path class=\"country\" d=\"M315 370L333 359 346 379 330 399 314 389Z\"/><path class=\"country\" d=\"M502 215L531 187 514 313 487 348 478 318Z\"/><g id=\"contours\" class=\"terrain-lines\"></g><rect x=\"85\" y=\"35\" width=\"390\" height=\"440\" filter=\"url(#noise)\" style=\"pointer-events:none\"/><g id=\"maplabels\"><text x=\"132\" y=\"115\">ANGOLA</text><text x=\"250\" y=\"90\">ZÂMBIA</text><text x=\"145\" y=\"260\" transform=\"rotate(-76 145 260)\">NAMÍBIA</text><text x=\"245\" y=\"245\">BOTSWANA</text><text x=\"314\" y=\"172\">ZIMBABWE</text><text x=\"410\" y=\"242\" transform=\"rotate(-65 410 242)\">MOÇAMBIQUE</text><text x=\"230\" y=\"402\">ÁFRICA DO SUL</text><text x=\"90\" y=\"488\" style=\"font-size:9px;fill:#647e7d\">OCEANO ATLÂNTICO</text><text x=\"401\" y=\"465\" style=\"font-size:9px;fill:#647e7d\">OCEANO ÍNDICO</text></g><g id=\"pins\"></g></g></svg><div class=\"zoom\"><button id=\"plus\" aria-label=\"Aumentar mapa\">+</button><button id=\"minus\" aria-label=\"Diminuir mapa\">−</button></div><div class=\"legend\"><i></i> Potencial análogo · seleção exploratória</div><div class=\"mapnote\">MAPA ESQUEMÁTICO · NÃO UTILIZAR PARA NAVEGAÇÃO</div></div>\n<aside class=\"detail\" id=\"detail\"></aside></section>\n<section class=\"bottom\"><article class=\"card\" id=\"method\"><div class=\"cardhead\"><h2>Uma comparação que se explica</h2><small>01 / MÉTODO</small></div><p>Ajuste os pesos para a sua pergunta de investigação. A pontuação usa a média ponderada dos critérios sintéticos disponíveis.</p><div class=\"weights\" id=\"weights\"></div><p id=\"formula\"></p></article><article class=\"card\"><div class=\"cardhead\"><h2>Assistente de investigação</h2><span class=\"badge\" id=\"ai-mode\">NEMOTRON · DEMO</span></div><div id=\"answer\" aria-live=\"polite\">Selecione um local e pergunte sobre o seu potencial científico. No modo demo, a síntese é construída a partir do catálogo sintético, sem inferência de IA.</div><form class=\"question\" id=\"chat\"><input id=\"question\" aria-label=\"Pergunta ao assistente\" placeholder=\"Por que estudar este local?\" maxlength=\"1000\" required><button class=\"primary\" id=\"ask\" aria-label=\"Enviar pergunta\">↗</button></form></article></section>\n<section class=\"stack\" id=\"tools\"><a href=\"https://www.nvidia.com/en-us/ai-data-science/foundation-models/nemotron/\" target=\"_blank\" rel=\"noreferrer\">NVIDIA Nemotron ↗<span>Assistente · API configurável</span></a><a href=\"https://jmars.mars.asu.edu/\" target=\"_blank\" rel=\"noreferrer\">JMARS ↗<span>Análise planetária externa</span></a><a href=\"https://mars.asu.edu/data/\" target=\"_blank\" rel=\"noreferrer\">MOLA ↗<span>Referência topográfica · Marte</span></a><a href=\"https://pds-geosciences.wustl.edu/missions/lro/lola.htm\" target=\"_blank\" rel=\"noreferrer\">LOLA ↗<span>Referência topográfica · Lua</span></a><a href=\"https://qgis.org/\" target=\"_blank\" rel=\"noreferrer\">QGIS ↗<span>Exportação GeoJSON · WGS 84</span></a><a href=\"https://manuals-ugcs.sphengineering.com/docs/importing-routes\" target=\"_blank\" rel=\"noreferrer\">UgCS ↗<span>Exportação KML · pontos de estudo</span></a></section><footer class=\"footer\"><span>AFRICA ANALOGS / A África também prepara o futuro da exploração espacial.</span><span>Protótipo conceptual · Dados por validar · Sem equivalência planetária certificada</span></footer></main><div id=\"toast\" role=\"status\"></div><dialog id=\"sources\"><h2>Proveniência e limitações</h2><div id=\"sourcebody\"></div><button id=\"close\">Fechar</button></dialog>\n<script src=\"/app.js\"></script></body></html>\n",js="const sites=[\n{id:'ntwetwe',name:'Ntwetwe Pan',country:'Botswana',type:'Bacia salina · Sedimentologia',lat:-20.5,lon:25.2,x:278,y:224,mars:[91,86,83,74],moon:[42,68,80,56],why:'Investigar deposição de sedimentos e superfícies salinas. A associação a ambientes marcianos é uma hipótese de trabalho.',missing:'Mineralogia in situ, sazonalidade e validação de campo.'},\n{id:'namib',name:'Deserto do Namibe',country:'Namíbia',type:'Campo de dunas · Processos eólicos',lat:-24.7,lon:15.3,x:177,y:299,mars:[84,93,91,65],moon:[36,71,88,60],why:'Estudar transporte eólico e mobilidade em areia. A atmosfera terrestre e a gravidade diferem das condições planetárias.',missing:'Granulometria, resistência do solo e dados meteorológicos locais.'},\n{id:'etosha',name:'Etosha Pan',country:'Namíbia',type:'Planície salina · Superfície sazonal',lat:-18.8,lon:16.3,x:190,y:199,mars:[82,79,81,69],moon:[39,62,74,54],why:'Explorar processos de evaporação e transformação de superfícies salinas ao longo do tempo.',missing:'Medições de salinidade e séries temporais verificadas.'},\n{id:'karoo',name:'Grande Karoo',country:'África do Sul',type:'Terreno árido · Geologia sedimentar',lat:-32.3,lon:22.5,x:267,y:409,mars:[76,81,79,83],moon:[53,74,68,77],why:'Explorar terrenos áridos e operações de campo em paisagens sedimentares.',missing:'Mapeamento local de litologias, declives e acessibilidade.'},\n{id:'lesoto',name:'Terras altas do Lesoto',country:'Lesoto',type:'Terreno basáltico · Relevo montanhoso',lat:-29.5,lon:28.5,x:330,y:380,mars:[71,65,44,84],moon:[83,79,45,88],why:'Investigar terrenos basálticos e testes de mobilidade em relevo acidentado; a composição precisa de confirmação local.',missing:'Petrografia, rugosidade medida e validação de declives.'}];\nlet selected=sites[0],target='Mars',weights=[30,30,25,15],zoom=1;const criteria=['Geologia / mineralogia','Topografia','Aridez','Mobilidade'];const $=s=>document.querySelector(s);const score=s=>{const total=weights.reduce((a,b)=>a+b,0);return total?Math.round(s[target.toLowerCase()].reduce((a,b,i)=>a+b*weights[i],0)/total):null};\nfunction render(){const query=$('#search').value.toLocaleLowerCase('pt');const visible=sites.filter(s=>(!$('#country').value||s.country===$('#country').value)&&(s.name+' '+s.country+' '+s.type).toLocaleLowerCase('pt').includes(query)).sort((a,b)=>(score(b)||0)-(score(a)||0));if(visible.length&&!visible.includes(selected))selected=visible[0];$('#count').textContent=String(visible.length).padStart(2,'0');$('#sites').replaceChildren();for(const s of visible){let b=document.createElement('button');b.className='site'+(selected===s?' selected':'');b.innerHTML=`<b>${score(s)??'—'}<small> /100</small></b><strong>${s.name}</strong><span>${s.country} · ${s.type.split(' · ')[0]}</span>`;b.onclick=()=>{selected=s;render()};$('#sites').append(b)}if(!visible.length)$('#sites').innerHTML='<p class=\"empty\">Nenhum local encontrado. Experimente outro filtro.</p>';$('#pins').innerHTML=visible.map(s=>`<circle tabindex=\"0\" role=\"button\" aria-label=\"Selecionar ${s.name}\" data-id=\"${s.id}\" class=\"pin ${selected===s?'chosen':''}\" cx=\"${s.x}\" cy=\"${s.y}\" r=\"8\"><title>${s.name}</title></circle>`).join('');document.querySelectorAll('.pin').forEach(p=>{const choose=()=>{selected=sites.find(s=>s.id===p.dataset.id);render()};p.onclick=choose;p.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose()}}});if(!visible.length){$('#detail').innerHTML='<h2>Sem resultados</h2><p class=\"sub\">Altere a pesquisa ou a região para explorar um local.</p>';return}const s=selected,v=s[target.toLowerCase()];$('#detail').innerHTML=`<div><div class=\"eyebrow\">POTENCIAL ANÁLOGO / ${target==='Mars'?'MARTE':'LUA'}</div><h2>${s.name}</h2><div class=\"sub\">${s.country}<br>${s.lat.toFixed(2)}°, ${s.lon.toFixed(2)}° · posição aproximada</div><div class=\"scorebox\"><div class=\"ring\">${score(s)??'—'}</div><div><p>Semelhança exploratória</p><small>DADOS SINTÉTICOS / 100</small></div></div></div><div>${criteria.map((c,i)=>`<div class=\"metric\"><div><span>${c}</span><span>${v[i]} / 100</span></div><section class=\"bar\"><i style=\"width:${v[i]}%\"></i></section></div>`).join('')}</div><div><div class=\"notice\">Hipótese de investigação. A pontuação não resulta de medições MOLA/LOLA nem certifica equivalência planetária.</div><button class=\"primary\" id=\"explain\">Explorar relevância científica ↗</button><button id=\"geo\">↓ GeoJSON para QGIS</button><button id=\"kml\">↓ Pontos KML para UgCS</button><button id=\"provenance\">Fontes e limitações</button></div>`;$('#geo').onclick=exportGeo;$('#kml').onclick=exportKml;$('#explain').onclick=()=>{$('#question').value='Qual é o potencial científico e quais são as limitações?';$('#chat').requestSubmit();$('#answer').scrollIntoView({behavior:'smooth',block:'center'})};$('#provenance').onclick=()=>{$('#sourcebody').innerHTML=`<p><b>${s.name}</b> — catálogo conceptual baseado na proposta Africa Analogs. Coordenadas aproximadas, para descoberta.</p><p>Similaridades: valores sintéticos definidos para demonstrar o método. Data de aquisição, resolução espacial e incerteza quantitativa: não disponíveis. Nenhum raster científico foi carregado.</p><p>Dados em falta: ${s.missing}</p><p>Referência planetária selecionada: ${target==='Mars'?'<a href=\"https://mars.asu.edu/data/\" target=\"_blank\" rel=\"noreferrer\">MOLA / ASU</a>':'<a href=\"https://pds-geosciences.wustl.edu/missions/lro/lola.htm\" target=\"_blank\" rel=\"noreferrer\">LOLA / PDS</a>'}. Estas fontes são referências externas, sem comparação automática neste protótipo.</p><p>JMARS: análise externa dos dados planetários. QGIS: importação do catálogo GeoJSON. UgCS: pontos de reconhecimento exportados em KML; não constituem uma rota de voo.</p>`;$('#sources').showModal()};$('#formula').textContent=weights.some(Boolean)?`S = Σ(peso × similaridade) / Σ(pesos) · soma dos pesos: ${weights.reduce((a,b)=>a+b,0)}. Incerteza não quantificada.`:'Defina pelo menos um peso maior que zero para calcular a pontuação.'}\n$('#weights').innerHTML=criteria.map((c,i)=>`<label>${c}<span id=\"w${i}\">${weights[i]}</span><input type=\"range\" min=\"0\" max=\"100\" value=\"${weights[i]}\" data-i=\"${i}\" aria-label=\"Peso: ${c}\"></label>`).join('');document.querySelectorAll('[data-i]').forEach(el=>el.oninput=()=>{weights[+el.dataset.i]=+el.value;$('#w'+el.dataset.i).textContent=el.value;render()});document.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{target=b.dataset.target;document.querySelectorAll('[data-target]').forEach(x=>x.classList.toggle('active',x===b));$('#answer').textContent='Destino alterado. Faça uma nova pergunta para analisar o local com esta referência.';render()});$('#search').oninput=render;$('#country').onchange=render;$('#relief').onchange=e=>$('#contours').style.display=e.target.checked?'':'none';$('#labels').onchange=e=>$('#maplabels').style.display=e.target.checked?'':'none';$('#close').onclick=()=>$('#sources').close();function zoomTo(n){zoom=Math.max(1,Math.min(2.4,n));$('#geography').setAttribute('transform',`translate(${300*(1-zoom)},${300*(1-zoom)}) scale(${zoom})`)}$('#plus').onclick=()=>zoomTo(zoom+.2);$('#minus').onclick=()=>zoomTo(zoom-.2);$('#contours').innerHTML=Array.from({length:26},(_,i)=>`<path d=\"M${120+i*3} 145 Q${220+i*6} ${160+i*7} ${160+i*4} 310 T${215+i*6} 440\"/>`).join('');\nfunction download(name,data,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#toast').textContent='Ficheiro exportado · dados de demonstração';$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}\nfunction exportGeo(){download('africa-analogs-'+selected.id+'.geojson',JSON.stringify({type:'FeatureCollection',features:[{type:'Feature',geometry:{type:'Point',coordinates:[selected.lon,selected.lat]},properties:{name:selected.name,country:selected.country,target,score:score(selected),synthetic:true,coordinate_accuracy:'approximate',source:'Africa Analogs conceptual proposal',acquired_at:null,resolution_m:null,missing:selected.missing,weights:Object.fromEntries(criteria.map((c,i)=>[c,weights[i]]))}}]},null,2),'application/geo+json')}\nfunction exportKml(){download('reconhecimento-'+selected.id+'.kml',`<?xml version=\"1.0\" encoding=\"UTF-8\"?><kml xmlns=\"http://www.opengis.net/kml/2.2\"><Document><name>Africa Analogs — ponto de estudo</name><Placemark><name>${selected.name}</name><description>DEMO: coordenadas aproximadas. Ponto de interesse para revisão no UgCS; sem altitude nem rota operacional.</description><Point><altitudeMode>clampToGround</altitudeMode><coordinates>${selected.lon},${selected.lat},0</coordinates></Point></Placemark></Document></kml>`,'application/vnd.google-earth.kml+xml')}\n$('#chat').onsubmit=async e=>{e.preventDefault();if(!$('#question').value.trim())return;const s=selected,planet=target;$('#ask').disabled=true;$('#answer').textContent='A preparar análise…';try{const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:$('#question').value,site_id:s.id,target:planet,score:score(s),weights})});if(!r.ok)throw Error('O serviço de IA está indisponível. Tente novamente.');const d=await r.json();$('#ai-mode').textContent=d.mode==='live'?'NEMOTRON · LIGADO':'NEMOTRON · DEMO';$('#answer').textContent=d.answer}catch(err){$('#answer').textContent=err.message}finally{$('#ask').disabled=false}};render();\n";
export default {async fetch(request,env){
const url=new URL(request.url);
if(url.pathname==='/api/chat'){
 if(request.method!=='POST')return new Response('Method not allowed',{status:405});
 if(Number(request.headers.get('content-length'))>10000)return new Response('Too large',{status:413});
 let body;try{const raw=await request.text();if(raw.length>10000)return new Response('Too large',{status:413});body=JSON.parse(raw)}catch{return new Response('Invalid JSON',{status:400})}
 const site=sites.find(s=>s.id===body.site_id);if(!site||!['Mars','Moon'].includes(body.target)||typeof body.question!=='string'||!body.question.trim()||body.question.length>1000)return new Response('Invalid request',{status:400});
 const context=JSON.stringify({site,target:body.target,data_status:'Synthetic demonstration, not measured',sources:{MOLA:'https://mars.asu.edu/data/',LOLA:'https://pds-geosciences.wustl.edu/missions/lro/lola.htm'}});
 if(env.NVIDIA_API_KEY&&env.NEMOTRON_MODEL){
 try{const result=await fetch('https://integrate.api.nvidia.com/v1/chat/completions',{method:'POST',headers:{Authorization:'Bearer '+env.NVIDIA_API_KEY,'Content-Type':'application/json'},signal:AbortSignal.timeout(25000),body:JSON.stringify({model:env.NEMOTRON_MODEL,messages:[{role:'system',content:'És o assistente Africa Analogs. Responde em português apenas com base no contexto. Distingue dados sintéticos, hipóteses e limitações. Não alegues ter analisado rasters, consultado fontes ou validado equivalência. As fontes são referências para trabalho futuro. Nunca inventes medições. Contexto: '+context},{role:'user',content:body.question}],max_tokens:650,temperature:0.2})});if(!result.ok)return Response.json({error:'Nemotron unavailable'},{status:502});const data=await result.json();const answer=data.choices?.[0]?.message?.content;if(!answer)return new Response('Empty model response',{status:502});return Response.json({mode:'live',answer})}catch{return Response.json({error:'Nemotron request failed'},{status:502})}
 }
 const answer='SÍNTESE DEMONSTRATIVA · SEM INFERÊNCIA NEMOTRON\n\n'+site.name+' → '+(body.target==='Mars'?'Marte':'Lua')+'\n'+site.why+'\n\nPara esta pergunta, a evidência disponível limita-se ao catálogo conceptual. Os valores mostrados são sintéticos. A interpretação exige validação específica para o destino selecionado.\n\nDados em falta: '+site.missing+'\n\nPróximos passos: examinar a referência '+(body.target==='Mars'?'MOLA':'LOLA')+' no JMARS, caracterizar o local terrestre no QGIS e rever pontos de reconhecimento no UgCS. Não foi realizada análise de rasters nem planeamento operacional.\n\nReferência externa: '+(body.target==='Mars'?'https://mars.asu.edu/data/':'https://pds-geosciences.wustl.edu/missions/lro/lola.htm');
 return Response.json({mode:'demo',answer});
}
if(url.pathname!=='/'&&url.pathname!=='/app.js')return new Response('Not found',{status:404});
return new Response(url.pathname==='/app.js'?js:html,{headers:{'Content-Type':url.pathname==='/app.js'?'text/javascript; charset=utf-8':'text/html; charset=utf-8','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin','Content-Security-Policy':"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'"}})
}};